from pathlib import Path
import runpy

ROOT = Path(__file__).resolve().parents[1]
api = runpy.run_path(str(ROOT / 'research/build-growth-pages.py'))
body = '''<section class="tool-panel" aria-labelledby="review-title"><h2 id="review-title">Review a redirect map</h2>
<p>Use exact local paths. Required map headers: <code>source_path,destination_path</code>. Optional: <code>decision,status_code</code>. Decisions are redirect, keep or remove; a map without a decision column is treated as redirects. Add an old-URL inventory with a <code>path</code> or <code>existing_path</code> header to check coverage.</p>
<form id="redirect-review"><label for="redirect-file">Map CSV file (optional)<input id="redirect-file" type="file" accept=".csv,text/csv" /></label><label for="redirect-csv">Map CSV<textarea id="redirect-csv" rows="9" spellcheck="false" required placeholder="source_path,destination_path,decision,status_code"></textarea></label>
<label for="inventory-file">Old-URL inventory file (optional)<input id="inventory-file" type="file" accept=".csv,text/csv" /></label><label for="inventory-csv">Old-URL inventory CSV<textarea id="inventory-csv" rows="5" spellcheck="false" placeholder="path"></textarea></label>
<p>Up to 2,000 rows and 500 KB per input. Comma, semicolon, tab and pipe-delimited CSV are supported. File contents and paths stay in this browser.</p>
<div class="tool-actions"><button class="button" type="submit">Review map</button><button type="button" class="button tool-secondary" id="redirect-example">Try synthetic example</button><button type="button" class="button tool-secondary" id="download-review" disabled>Download review</button></div></form>
<p id="redirect-status" class="tool-status" role="status" aria-live="polite"></p><div id="redirect-results" class="redirect-findings"></div>
<noscript><p>JavaScript is required for the local review. The examples and guidance below remain available.</p></noscript></section>
'''
body += api['section']('A worked review', '<p>The original synthetic map sends <code>/old</code> through <code>/middle</code>, has a loop between two paths and lacks a decision for <code>/missing</code> in the inventory. The reviewed example points the changed paths directly to <code>/new</code>, retains the contact path, records a removal decision and explicitly keeps the missing path.</p><p><a href="/resources/redirect-map-example.csv" download>Download the original map</a> and <a href="/resources/redirect-map-reviewed-example.csv" download>the manually reviewed map</a>. These decisions are fictional and illustrate the workflow; choose destinations for your actual content.</p><p>Use this inventory with the example: <code>path</code>, followed by one path per line: <code>/old</code>, <code>/contact</code>, <code>/retired</code>, <code>/missing</code>. The reviewed example has zero findings for that inventory under the supported checks.</p>')
body += api['section']('What this review covers', '<ul><li><strong>Map consistency</strong> Competing sources, unsupported paths, invalid decision/status combinations, loops and multi-hop chains.</li><li><strong>Inventory decisions</strong> Identify old paths without a valid unique keep, redirect or remove decision.</li><li><strong>Human review</strong> A finding points to a decision to inspect; the tool does not choose where your content belongs.</li><li><strong>Export</strong> Download a text review without uploading the map or changing your website.</li></ul><p>Paths are case-sensitive and trailing slashes are distinct. Full URLs, query strings, fragments, patterns and dot segments are unsupported. Regex matching, live HTTP status, destination relevance and server configuration need separate verification.</p>')
body += api['section']('Use it in a migration plan', '<p>Read the <a href="/insights/wordpress-to-nextjs-migration-checklist/">WordPress-to-Next.js planning guide</a> and record the source of your old-URL inventory. Check real deployed responses after the reviewed rules are applied. A clean spreadsheet is only one part of launch verification.</p><p>For implementation, explore <a href="/services/nextjs-development/">Next.js development</a> or <a href="/services/agency-development-support/">agency implementation support</a>. The separate <a href="/tools/csv-cleaner/">CSV cleaner</a> can help with general file cleanup; this checker focuses on URL decisions.</p>')
api['render']('/tools/redirect-map-checker/', 'Free Redirect Map Checker | CSV Chains, Loops & URL Coverage', 'Review a CSV redirect map for chains, loops, competing sources and missing old-URL decisions. Free local browser checks with a downloadable review.', 'Redirect map checker for website migrations', 'Review the structure of your migration decisions before deployment. Check a map and an optional old-URL inventory locally; live websites are not fetched.', body, kind='tool', scripts=['/js/csv-cleaner-core.js', '/js/redirect-map-core.js', '/js/redirect-map.js'])
print('Rendered redirect-map checker.')
